// COPPERHALL-01: THE COPPER HALL, THE SHOWCASE LANDMARK (owner 11-01 showcase item 5; design docs/reports/copperhall-design-2026-11-01.md
// r2, both engines APPROVE). PURE: the switch, the opening rule, the fixed site on the town plan's `hall` plot (sector SW), the stand
// domain, the record. Nothing here touches a bot or a file. The visit is skills.mjs build_shop's ordinary blueprint visit
// (buildrun.mjs runVisit) with this domain, the siting below in place of buildsite.mjs siteBlueprint's sector search.
//
// THE BUILDING: blueprints/hall@1.json (generated by docs/reports/copperhall-2026-11-01/make_hall.py), 477 cells on a 15 x 13 pad:
// a stone-brick pad, a step ring at s+1 outside walls set back one cell, a stone-brick base course and a plank upper course with
// glass bays, ten cut-copper pilasters (both courses + a cap in the eave line) and a 3-cell copper lintel over the 3-wide doorway,
// stone-brick eaves and a plank roof at s+3; four floor torches and four depot chests inside. The copper role has NO fallback: a
// placed cell is never rebuilt, so a stone pilaster would freeze the copper look out for good. Unwaxed, it weathers in place
// (buildrun.mjs strips exposed_/weathered_/oxidized_ when it verifies a placed cell).
//
// WHEN IT OPENS (design section 4, Claude design r1 blocker 2): the project is only OFFERED (shop.mjs activeProject skips a
// `waiting` project) and only SITED once the town holds the copper for every cut-copper batch above the project floor -- loose
// copper_ingot >= the project floor (PROJECT_RESERVE_KEEP of the reserve: 103 of 512) + 36 x the batches the town's cut copper
// still lacks (319 on 11-01: 33 cut needed, 10 in town). Opening early would stall between batches, and a project with no
// placement for PROJECT_STALL_MS stops being active, its floor back at 512 the town has never held: the copper draws would lock
// themselves out (two correct guards composing into a dead end). The shell never waits for copper once open.
//
// COPPERHALL=off is the kill switch (never offered, never sited). On only in COPPERHALL_POOLS (default 'showcase').

import { screenSite, proveSite, replantFor, walkFrom, overlay, reservations, billOf, WALK_R } from './buildsite.mjs'

export const HALL_PLOT = 'hall'
export const HALL_BLUEPRINT = 'hall@1'
export const HALL_BUILDERS = 2
export const HALL_CUT_NEEDED = 33             // the blueprint's copper cells (10 pilasters x 2 courses, 10 caps, 3 lintel)
export const CUT_PER_BATCH = 4                // mats.mjs cut_copper: 36 copper_ingot -> 4 copper_block -> 4 cut_copper
export const INGOTS_PER_BATCH = 36
export const PROJECT_KEEP = 0.2               // mats.mjs PROJECT_RESERVE_KEEP (the floor kept while a project is active)
// THE PAD on the plan's hall plot, from home (design 1.2): x -21..-7, z 21..33, orient E (u along +x, v along +z), the doorway in
// the front wall (v 1) facing north toward the plaza. The ring is x -22..-6, z 20..34: one column clear of the tree farm, one row
// clear of the wall (z 36)
export const HALL_PAD = Object.freeze({ dx: -21, dz: 21, orient: 'E', sector: 'SW' })
// THE HALL'S EARTHWORK (offline on the showcase's own terrain, 11-02 00:41Z region export): the 15 x 13 pad spans ground 62..74 on
// the SW terrace (bot pits and pillars on a 65 / 68 step); the least earthwork is at floor 65, fill 110 + cut 135, at most 3 a
// column -- the house's EARTH (fill 40, cut 30) refuses every level. The hall's limits: 5 a column, 160 each
export const HALL_EARTH = Object.freeze({ col: 5, fill: 160, cut: 160 })
export const HALL_DOMAIN = 3                  // the stands' domain: the pad + this, never another record's box (+ 1)

/** THE SWITCH -> bool. COPPERHALL=on|off; unset = on only in the pools COPPERHALL_POOLS names (default 'showcase'). Pure. */
export function copperhallOn (env = process.env, pool = '') {
  const v = String(env?.COPPERHALL ?? '').trim().toLowerCase()
  if (['on', '1', 'true', 'yes'].includes(v)) return true
  if (['off', '0', 'false', 'no'].includes(v)) return false
  const pools = String(env?.COPPERHALL_POOLS ?? 'showcase').split(',').map(s => s.trim()).filter(Boolean)
  return pools.includes(String(pool))
}

/**
 * THE OPENING RULE -> { open, need, have, why }. Pure. `ingots` the town's loose copper_ingot, `cut` its cut_copper, `reserve` the
 * copper_ingot reserve (mats reserve table; 512). Needs the project floor (ceil(PROJECT_KEEP x reserve)) plus INGOTS_PER_BATCH per
 * cut-copper batch the bill still lacks. An unknown count (not a number) never opens.
 */
export function hallOpening ({ ingots = null, cut = null, reserve = 512, needed = HALL_CUT_NEEDED } = {}) {
  if (!Number.isFinite(ingots) || !Number.isFinite(cut)) return { open: false, need: null, have: ingots, why: 'copper_unknown' }
  const floor = Math.ceil(PROJECT_KEEP * (Number(reserve) || 0))
  const batches = Math.ceil(Math.max(0, needed - cut) / CUT_PER_BATCH)
  const need = floor + INGOTS_PER_BATCH * batches
  return { open: ingots >= need, need, have: ingots, why: ingots >= need ? 'ok' : 'copper_wait', floor, batches }
}

/**
 * THE TOWN'S COPPER from the town index's entries (townindex.mjs readIndex: "x,y,z" -> { obs: { names: { name: [n, slots] } }, ... })
 * -> { ingots, cut, containers, stale } | { unknown: true }. Pure. Each container's LATEST observation counts, fresh or stale (LIVE
 * 11-02 01:14-01:39Z: matsTownStock sums only FRESH entries in loaded chunks, and the copper chests' observations were older than
 * INDEX_STALE_MS -- every gate row read 0 ingots while the index showed 130); a `dirty` entry (a mutation under way) and an entry
 * with no observation count nothing (the count can only be low, never high). No entries at all: unknown.
 */
export function townCopperOf (entries, stateOf = () => 'known') {
  if (!entries || typeof entries !== 'object') return { unknown: true }
  let ingots = 0, cut = 0, containers = 0, stale = 0, raw = 0, blocks = 0
  // a container another entry's NEWER observation names among its halves (`obs.h`: a single chest that became the other half of a
  // double chest) is that entry's now, not its own (Codex r3 BLOCK: both counted, 160 read as 320)
  const covered = new Map()
  for (const [k, e] of Object.entries(entries)) {
    for (const h of Array.isArray(e?.obs?.h) ? e.obs.h : []) if (h !== k) covered.set(h, Math.max(covered.get(h) ?? -Infinity, Number(e.obs.at) || 0))
  }
  for (const [k, e] of Object.entries(entries)) {
    if (!/^-?\d+,-?\d+,-?\d+$/.test(k) || !e?.obs?.names) continue
    if (covered.has(k) && covered.get(k) >= (Number(e.obs.at) || 0)) continue
    let st = 'unknown'
    try { st = stateOf(e) } catch { st = 'unknown' }
    if (st !== 'known' && st !== 'stale') continue
    containers++
    if (st === 'stale') stale++
    ingots += Number(e.obs.names.copper_ingot?.[0]) || 0
    cut += Number(e.obs.names.cut_copper?.[0]) || 0
    // copperrun-01: raw copper (the town smelt job's input: it becomes ingots there) and copper blocks (counted, never drawn:
    // mats.mjs cut_copper draws copper_ingot only, so a block in a chest funds no batch and never opens the hall)
    raw += Number(e.obs.names.raw_copper?.[0]) || 0
    blocks += Number(e.obs.names.copper_block?.[0]) || 0
  }
  return containers ? { ingots, cut, containers, stale, raw, blocks } : { unknown: true }
}

/** `_copperhall_mode` row detail. Pure. */
export const copperhallModeDetail = (on, o = null) => `on=${on ? 1 : 0} plot=${HALL_PLOT} blueprint=${HALL_BLUEPRINT} builders=${HALL_BUILDERS} cut_needed=${HALL_CUT_NEEDED}` +
  (o ? ` open=${o.open ? 1 : 0} ingots=${o.have ?? '-'} cut=${o.cut ?? '-'} need=${o.need ?? '-'} containers=${o.containers ?? '-'} stale=${o.stale ?? '-'} why=${o.why}` : '')

/** The hall's anchor for a plan -> { anchor: {x, z}, orient } | { why }. Pure. The plan must have a `hall` plot in sector SW. */
export function hallAnchor (plan) {
  const home = plan?.home
  if (!home || !Number.isFinite(home.x) || !Number.isFinite(home.z)) return { why: 'no_plan' }
  const p = (plan.plots ?? []).find(q => q?.id === HALL_PLOT)
  if (!p) return { why: 'no_hall_plot' }
  if (p.sector !== HALL_PAD.sector) return { why: `hall_sector_${p.sector ?? 'none'}` }
  return { anchor: { x: home.x + HALL_PAD.dx, z: home.z + HALL_PAD.dz }, orient: HALL_PAD.orient }
}

/** A record's x/z box ([x0, z0, x1, z1]) -> bool for (x, z) within it grown by `m`. */
const inBox = (b, x, z, m = 0) => Array.isArray(b) && b.length === 4 && x >= b[0] - m && x <= b[2] + m && z >= b[1] - m && z <= b[3] + m

/**
 * THE STANDS' DOMAIN of a hall pad box ([x0, z0, x1, z1]) among the town's other records -> (x, z) -> bool. Pure. Within
 * HALL_DOMAIN of the pad, never inside another record's box grown by 1 (a builder never stands on the tree farm's rows or the wall).
 */
export function hallDomain (box, others = [], { reach = HALL_DOMAIN, gap = 1 } = {}) {
  const boxes = (others ?? []).map(r => r?.box).filter(b => Array.isArray(b) && b.length === 4)
  return (x, z) => inBox(box, x, z, reach) && !boxes.some(b => inBox(b, x, z, gap))
}
/** The pad box of the hall at `anchor` (15 x 13, orient E) -> [x0, z0, x1, z1]. Pure. */
export const hallBox = (anchor, bp) => [anchor.x, anchor.z, anchor.x + (bp?.footprint?.u ?? 15) - 1, anchor.z + (bp?.footprint?.v ?? 13) - 1]

/**
 * THE SITE AND ITS PROOF -> { ok, why, detail?, record }. Pure over `read`. The fixed pad (hallAnchor), screened by buildsite.mjs
 * screenSite with the hall's domain (reservations, zones, trees, the floor level and its earthwork -- the house's own column
 * checks), proven by proveSite with the same domain (every placement has a stand; the interior is walked to through the doorway),
 * the felled trunks' replant cells found as siteBlueprint finds them. The other records are zones at margin 0 (their boxes: the
 * ring's west column is one clear of the tree farm by design) and the stand domain keeps off them by 1.
 *   ctx  { zones, wells, farm, z0 } (reservations), { others } the other records, { stood } the walk's seeds, { now }
 */
export function hallSite (read, plan, bp, ctx = {}) {
  const a = hallAnchor(plan)
  if (!a.anchor) return { ok: false, why: a.why }
  const home = plan.home
  const others = (ctx.others ?? []).filter(Boolean)
  const box = hallBox(a.anchor, bp)
  const domain = hallDomain(box, others)
  const zones = [...(ctx.zones ?? []), ...others.filter(r => Array.isArray(r?.box) && r.box.length === 4).map(r => ({ box: [r.box[0], -64, r.box[1], r.box[2], 320, r.box[3]], why: `project:${r.plot ?? '?'}` }))]
  const res = reservations(plan, { ...ctx, zones })
  // the screen's domain: the pad and its ring, on no other record's box (the ring's west column touches the tree farm's edge);
  // the stands' domain (proof and visit) keeps one more off every other record
  const site = screenSite(read, home, bp, a.anchor, a.orient, res, { domain: hallDomain(box, others, { reach: 1, gap: 0 }), earth: HALL_EARTH })
  if (!site.ok) return { ok: false, why: site.why, detail: site.detail }
  const stood = ctx.stood ?? []
  const p = proveHall(read, home, bp, site, { stood, domain })
  if (!p.ok) return { ok: false, why: p.why, detail: p.detail }
  const over = new Map()
  for (const c of site.clear) over.set(c.at.join(','), { name: 'air', boundingBox: 'empty' })
  for (const c of p.fill) over.set(c.join(','), { name: 'cobblestone', boundingBox: 'block' })
  const rp = replantFor(read, home, site, res, walkFrom(overlay(read, over), home, new Set(), WALK_R, { stood }))
  if (!rp.ok) return { ok: false, why: 'no_replant_cell' }
  const xs = site.pad.map(c => c[0]), zs = site.pad.map(c => c[1])
  const record = {
    v: 1, blueprint: bp.id, plot: HALL_PLOT, home, sector: HALL_PAD.sector, sector_source: 'plan', orient: site.orient, anchor: [site.anchor.x, site.anchor.z],
    box: [Math.min(...xs), Math.min(...zs), Math.max(...xs), Math.max(...zs)], s: site.s, floor: site.g0,
    earthwork: { fill: p.fill.length, cut: site.cut.length, litter: site.litter, voids: p.voids.length },
    fill: p.fill, voids: p.voids, clear: site.clear.map(c => ({ at: c.at, kind: c.kind, name: c.name })),
    trees: site.trees.map(t => ({ base: t.base, species: t.species, logs: t.logs })), felled: site.felled, replant: rp.cells,
    cells: p.cells, segments: p.segments, interior: p.interior, bom: billOf(bp, p.cells), builders_max: HALL_BUILDERS,
    structure_complete: false, plan: { gen: plan.gen }, stood_seeds: stood.length, sitedAt: ctx.now ?? 0,
  }
  return { ok: true, why: 'ok', record, site, proof: p }
}

/**
 * THE PROOF, WITH DEEP-PIT VOIDS -> proveSite's answer, plus `voids` (fill cells left out). Pure. The SW terrace holds 1-2 wide pits
 * bots dug, 3 deep below the floor (offline 11-02: `no_step earth 3 left, first fill@-12,63,26`): a pit's BOTTOM fill cell has no
 * stand (the rim's eye is 4.6 above its support, and the pit's own cells are still to place). A fill cell with another fill cell
 * ABOVE it in its column only supports that cell, which can rest on its side neighbours instead: it is left out (an air void under
 * the pad, covered; no block falls) and the proof is run again, at most MAX_VOIDS times. The top fill cell of a column, and every
 * other cell, must still be proven.
 */
export const MAX_VOIDS = 12
export function proveHall (read, home, bp, site, opts = {}) {
  let fill = [...site.fill]
  const voids = []
  for (;;) {
    const p = proveSite(read, home, bp, { ...site, fill }, opts)
    if (p.ok || p.why !== 'no_step' || voids.length >= MAX_VOIDS) return { ...p, voids, fill }
    const m = /^earth \d+ left, first fill@(-?\d+),(-?\d+),(-?\d+)$/.exec(String(p.detail ?? ''))
    if (!m) return { ...p, voids, fill }
    const [x, y, z] = [Number(m[1]), Number(m[2]), Number(m[3])]
    if (!fill.some(f => f[0] === x && f[2] === z && f[1] > y)) return { ...p, voids, fill }
    fill = fill.filter(f => !(f[0] === x && f[1] === y && f[2] === z))
    voids.push([x, y, z])
  }
}

/** The stands' domain for a sited hall RECORD (the visit's, runVisit `domain`) among the other records. Pure. */
export const hallRecordDomain = (rec, others = []) => (Array.isArray(rec?.box) && rec.box.length === 4 ? hallDomain(rec.box, others.filter(r => r !== rec && r?.plot !== HALL_PLOT)) : () => false)

// ---- COPPERRUN-01: THE HALL'S BILL DRIVES A COPPER GATHER ----------------------------------------------------------------------
// MEASURED on the showcase (48 h to 11-03 02:45Z, 10 bots, 293,405 rows): the hall waited `copper_wait` on every one of its 525
// gate rows (130-138 ingots, cut 10 -> 18, need 319 -> 247). No gather or mine targeted copper (0 of 3,198 gather/mine rows; the
// control: iron_ore 201, coal_ore 9, dirt 2,378); the only raw copper was incidental (41: mine 38, surface 3), and it went where
// it should (smelt_town 33, deposit 8; the well took none). Copper ore is in neither prompt.mjs INTERESTING_BLOCKS nor
// reflex.mjs SURVEY_BLOCKS, so the model is never shown it, and it does not tunnel (oretunnel.mjs tunnelKindsFor: iron, coal,
// diamond -- protected scope). Nothing in the bots asked for copper.
//
// THE RUN: while the town's hall is unsited and waiting on its copper (copperhall.mjs hallOpening), and the town's ingots plus its
// raw copper (the smelt job turns raw into ingots) are short of the opening's need, a bot the build order has no use for (shop.mjs
// buildIdle -- the branch that would otherwise send it on an expedition) gathers EXPOSED copper ore in reach: `gather` of that
// ore, whose own guards (town ground, keep-out, break veto, lava guard, six faces) decide every block exactly as for the model's
// gather. Buried ore is not offered (gather cannot tunnel to it and would fail `buried`). Never from a project's site (coalsite-01's
// rule, fail closed). An ore cell the last run was issued for and that is still there (the run did not take it) backs the bot off
// COPPER_RUN_BACKOFF_MS: no repeated walk at an ore gather cannot reach. The run never refuses anything: when it does not issue,
// the build order goes on to the expedition exactly as before.
//
// KILL SWITCH: COPPERRUN=off (never asked). It is asked only where the hall is on (COPPERHALL, default the showcase pool).

const cv = String((typeof process !== 'undefined' ? process.env?.COPPERRUN : '') ?? '').trim().toLowerCase()
export const COPPERRUN = Object.freeze({ on: !['off', '0', 'false', 'no'].includes(cv) })
/** The blocks that drop raw copper (vanilla 1.21: 2-5 each, more with fortune). */
export const COPPER_KINDS = Object.freeze(['copper_ore', 'deepslate_copper_ore'])
/** The run's ask: gather's `count` (a copper vein is up to 10 blocks; ~3.5 raw each). */
export const COPPER_RUN_COUNT = 16
/** No run while the bag carries this much copper (raw + ingots): it goes to town first (raw_copper / copper_ingot DEPOSIT_ALWAYS). */
export const COPPER_RUN_CARRY = 16
/** Free slots a run needs (the raw copper and what the digging yields). */
export const COPPER_RUN_MIN_FREE = 3
/** Charged at ISSUE: at most one run per bot per 10 min. */
export const COPPER_RUN_COOLDOWN_MS = 10 * 60 * 1000
/** The same ore cell still there at the next ask: the run did not take it; back off this long. */
export const COPPER_RUN_BACKOFF_MS = 30 * 60 * 1000
/** The world scan at most this often per bot. */
export const COPPER_RUN_SCAN_MS = 60 * 1000
/** The ore must be this close: gather's own default reach (skills.mjs gatherRun maxDistance 32). */
export const COPPER_ORE_RADIUS = 32

/**
 * HOW SHORT IS THE TOWN? -> { short, need, have } | null. Pure over hallOpenNow's answer (`need` hallOpening's, `have` the loose
 * ingots, `raw` the town's raw copper). Raw copper counts toward the target (the town smelt job makes it ingots); cut copper is
 * already in `need` (fewer batches). Unknown counts: null (the run does not issue).
 */
export function copperShort (gate) {
  if (!gate || !Number.isFinite(gate.need) || !Number.isFinite(gate.have)) return null
  const have = gate.have + Math.max(0, Number(gate.raw) || 0)
  return { short: Math.max(0, gate.need - have), need: gate.need, have }
}

/**
 * THE COPPER RUN -> { order, state, skip }. Pure; skills.mjs copperAsk supplies the readings and keeps `state`.
 *   on         COPPERRUN and the hall's own switch
 *   waiting    lazy -> bool: the hall is a project here and is unsited
 *   gate       lazy -> hallOpenNow's answer { open, need, have, raw, ... }
 *   held       the bag's raw_copper + copper_ingot
 *   freeSlots  36 - occupied slots
 *   tripPick   a stone-or-better pickaxe that can pay a trip (oretunnel.mjs hasTripPickaxe)
 *   site       lazy -> { ok, hit } where the bot stands against the projects' records (skills.mjs projectSiteNow)
 *   ore        lazy -> { block, dist, at: 'x,y,z' } | null: the nearest EXPOSED copper ore within COPPER_ORE_RADIUS, off home
 *   state      { lastIssuedAt, backoffUntil, lastScanAt, lastOre }
 * Cheap tests first; the readings only when everything else would issue. `skip` names why nothing was issued.
 */
export function copperRunOrder ({ now = 0, on = COPPERRUN.on, waiting = null, gate = null, held = 0, freeSlots = 0, tripPick = false,
                                  site = null, ore = null, state = {} } = {}) {
  const s = { ...state }
  const skip = why => ({ order: null, state: s, skip: why })
  if (!on) return skip('off')
  if (now - (s.lastIssuedAt ?? -Infinity) < COPPER_RUN_COOLDOWN_MS || now < (s.backoffUntil ?? 0)) return skip('cooldown')
  if ((Number(held) || 0) >= COPPER_RUN_CARRY) return skip('carrying')
  if ((Number(freeSlots) || 0) < COPPER_RUN_MIN_FREE) return skip('room')
  if (!tripPick) return skip('pickaxe')
  if (now - (s.lastScanAt ?? -Infinity) < COPPER_RUN_SCAN_MS) return skip('scan')
  s.lastScanAt = now
  if (lazy(waiting) !== true) return skip('not_waiting')
  const g = lazy(gate)
  if (g?.open) return skip('open')
  const sh = copperShort(g)
  if (!sh) return skip('copper_unknown')
  if (sh.short <= 0) return skip('stocked')
  const st = lazy(site)
  if (st?.ok !== true) return skip('site_unknown')
  if (st.hit) return skip('on_site')
  const o = lazy(ore)
  if (!o?.block || !COPPER_KINDS.includes(o.block)) return skip('no_ore')
  // the cell the last run was issued for is still ore: that run did not take it (unreachable, refused): back off, once per cell
  if (o.at && o.at === s.lastOre) { s.backoffUntil = now + COPPER_RUN_BACKOFF_MS; s.lastOre = null; return skip('same_ore') }
  s.lastIssuedAt = now
  s.lastOre = o.at ?? null
  return { order: { skill: 'gather', args: { block: o.block, count: COPPER_RUN_COUNT, copperrun: true },
                    why: `the town's copper hall needs ${sh.need} copper ingots to open and the town holds ${sh.have} (ingots + raw); ` +
                         `${o.block} ${Math.round(Number(o.dist) || 0)} blocks away -- mining it for the hall` },
           state: s, skip: null, short: sh }
}

/** The run's row detail (under 300 chars). */
export const copperRunDetail = ({ skip = null, issued = null, gate = null, held = 0, free = 0 } = {}) =>
  `${issued ? `issued block=${issued}` : `skip=${skip ?? '-'}`} ingots=${gate?.have ?? '?'} raw=${gate?.raw ?? '?'} blocks=${gate?.blocks ?? '?'} ` +
  `cut=${gate?.cut ?? '?'} need=${gate?.need ?? '?'} held=${held} free=${free}`
/** `_copperrun_mode` row detail. */
export const copperRunModeDetail = (on, hall) => `on=${on ? 1 : 0} hall=${hall ? 1 : 0} kinds=${COPPER_KINDS.join('+')} radius=${COPPER_ORE_RADIUS} count=${COPPER_RUN_COUNT} carry=${COPPER_RUN_CARRY} cooldown_min=${COPPER_RUN_COOLDOWN_MS / 60000} backoff_min=${COPPER_RUN_BACKOFF_MS / 60000}`

const lazy = x => (typeof x === 'function' ? x() : x)
